"use client";

import { loadFont } from "@remotion/google-fonts/Afacad";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  interpolateColors,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_RESOLUTION,
  DEFAULT_SETUP,
  DEFAULT_SNAG,
  lineWords,
  type StoryDipElementId,
  storyDipTimeline,
} from "./timeline";

const afacad = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface StoryBeat {
  slug: string;
  line: string;
}

export interface StoryDipProps {
  setup?: StoryBeat;
  snag?: StoryBeat;
  resolution?: StoryBeat;
  /** Weight of the story lines. */
  fontWeight?: number;
  /** Opacity the snag beat dims to as it falls. */
  dim?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Afacad by default. */
  fontFamily?: string;
  /** Size of the beats, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the beats writing in, the snag's fall and the
   * resolution's climb, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<StoryDipElementId>;
}

const THEMES = {
  dark: { bg: "#3A1F1A", ink: "#FBF3EA", accent: "#F2B544" },
  light: { bg: "#FBF6EE", ink: "#3B2414", accent: "#B07A00" },
} as const;

const LINE_TRACK = -0.02;
const SLUG_TRACK = 0.09;
const LH = 1.04;
const PX = 100;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_FALL = Easing.bezier(0.55, 0, 0.9, 0.45);
const EASE_CLIMB = Easing.bezier(0.45, 0, 0.12, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function useWidths(strings: string[], font: string) {
  const key = strings.join("\u0001");
  const [state, setState] = useState<{
    key: string;
    w: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("story-dip: measuring"));
  const released = useRef(false);
  const ref = useRef(strings);
  ref.current = strings;
  useEffect(() => {
    let live = true;
    Promise.all([afacad.waitUntilDone(), document.fonts.load(font)])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const w: Record<string, number> = {};
        if (ctx) ctx.font = font;
        for (const s of ref.current) {
          w[s] = ctx ? ctx.measureText(s).width / PX : s.length * 0.45;
        }
        setState({ key, w });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, font, handle]);
  return state && state.key === key ? state.w : null;
}

function wrapLines(ws: string[], adv: (s: string) => number, max: number) {
  const space = adv(" ");
  const lines: string[][] = [[]];
  let x = 0;
  for (const word of ws) {
    const w = adv(word);
    const cur = lines[lines.length - 1];
    if (cur.length > 0 && x + space + w > max) {
      lines.push([word]);
      x = w;
    } else {
      x += (cur.length > 0 ? space : 0) + w;
      cur.push(word);
    }
  }
  return lines;
}

function balancedLines(ws: string[], adv: (s: string) => number, max: number) {
  const base = wrapLines(ws, adv, max);
  if (base.length <= 1) return base;
  let lo = Math.max(...ws.map(adv));
  let hi = max;
  for (let k = 0; k < 18; k++) {
    const mid = (lo + hi) / 2;
    if (wrapLines(ws, adv, mid).length <= base.length) hi = mid;
    else lo = mid;
  }
  return wrapLines(ws, adv, hi);
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function StoryDip(props: StoryDipProps) {
  const {
    setup = DEFAULT_SETUP,
    snag = DEFAULT_SNAG,
    resolution = DEFAULT_RESOLUTION,
    fontWeight = 400,
    dim = 0.62,
    accent,
    ink: inkColor,
    background,
    fontFamily = afacad.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay);
  const t = frame * speed;
  const { width: W, height: H, durationInFrames: T } = useSceneConfig();
  // The schedule stretches with the clip itself, not with `speed`.
  const tl = useTimeline(storyDipTimeline, props, T, timing);
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = inkColor ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const beats = [setup, snag, resolution];
  const tokens = beats.map((b) => lineWords(b.line));
  const strings = Array.from(new Set([" ", ...tokens.flat()]));
  const w = useWidths(strings, `${fontWeight} ${PX}px "${fontFamily}"`);

  if (!w) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const unit = Math.min(W, H);
  const marginX = W * (portrait ? 0.05 : 0.045);
  const gutter = W * (portrait ? 0.03 : 0.025);
  const cols = portrait ? 2 : 3;
  const colW = (W - 2 * marginX - (cols - 1) * gutter) / cols;
  const colOf = portrait ? [0, 0, 1] : [0, 1, 2];
  const maxLines = portrait ? 5 : 4;
  const adv = (s: string) => (w[s] ?? 0) + LINE_TRACK * Array.from(s).length;

  let F = portrait ? W * 0.1 : H * 0.1;
  for (let k = 0; k < 60; k++) {
    const ok = tokens.every(
      (ws) => wrapLines(ws, adv, colW / F).length <= maxLines,
    );
    if (ok) break;
    F *= 0.96;
  }
  const S = Math.max(14, F * 0.3);
  const laid = tokens.map((ws) => balancedLines(ws, adv, colW / F));
  const slugBlock = S * 1.2 + S * 0.9;
  const heights = laid.map((l) => slugBlock + l.length * F * LH);

  const top = H * (portrait ? 0.08 : 0.06);
  const bottom = H * (portrait ? 0.92 : 0.94);
  const startTop = H * (portrait ? 0.4 : 0.5) - heights[0] / 2;
  const gapY = F * 0.6;
  const lowTop = bottom - heights[1];
  const highTop = top;

  const writes = [tl.get("setup"), tl.get("snag"), tl.get("resolution")];
  const fall = tl.get("fall");
  const climb = tl.get("climb");

  const snagStart = portrait
    ? Math.min(lowTop, startTop + heights[0] + gapY)
    : startTop;
  // Each beat is laid out where it ends up; the fall and the climb there are
  // a transform, since layout rounds a box and a baseline to whole pixels and
  // a block eased by `top` clicks down pixel by pixel.
  const tops = [startTop, lowTop, highTop];
  const travel = [
    () => 0,
    (tt: number) => {
      const fallen = interpolate(tt, [fall.start, fall.end], [0, 1], {
        ...CLAMP,
        easing: EASE_FALL,
      });
      const settle = interpolate(
        tt,
        [
          fall.end,
          fall.end + fall.beat("bounce"),
          fall.end + fall.beat("settle"),
        ],
        [0, 1, 0],
        { ...CLAMP, easing: Easing.bezier(0.45, 0, 0.55, 1) },
      );
      return (snagStart - lowTop) * (1 - fallen) + unit * 0.012 * settle;
    },
    (tt: number) => {
      const climbed = interpolate(tt, [climb.start, climb.end], [0, 1], {
        ...CLAMP,
        easing: EASE_CLIMB,
      });
      return (lowTop - highTop) * (1 - climbed);
    },
  ];

  const lowDim = interpolate(t, [fall.start, fall.end], [1, dim], CLAMP);
  const lift = interpolate(
    t,
    [climb.start + climb.beat("lift"), climb.end],
    [0, 1],
    {
      ...CLAMP,
      easing: Easing.bezier(0.45, 0, 0.55, 1),
    },
  );

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily,
      }}
    >
      <ScaleLayer scale={scale}>
        {beats.map((b, i) => {
          const x = marginX + colOf[i] * (colW + gutter);
          const write = writes[i];
          const rise = write.beat("rise");
          const slugE = interpolate(
            t,
            [write.start, write.start + rise],
            [0, 1],
            {
              ...CLAMP,
              easing: EASE_OUT,
            },
          );
          if (slugE <= 0.001) return null;
          const lines = laid[i];
          const step = write.beat("step");
          let idx = 0;
          const ink = i === 2 ? interpolateColors(lift, [0, 1], [fg, hi]) : fg;
          const inkOpacity = i === 1 ? lowDim : 1;
          const dy = travel[i](t);
          const travelling =
            Math.abs(travel[i](t + speed) - dy) > 1e-3 ||
            Math.abs(dy - travel[i](t - speed)) > 1e-3;
          return (
            <div
              key={`${b.slug}${String(i)}`}
              style={{
                position: "absolute",
                left: x,
                top: tops[i],
                width: colW,
                transform:
                  Math.abs(dy) > 1e-3 || travelling
                    ? `translateY(${dy}px)${glide(travelling)}`
                    : undefined,
              }}
            >
              <div
                style={{
                  fontSize: S,
                  fontWeight: 500,
                  letterSpacing: `${SLUG_TRACK}em`,
                  textTransform: "uppercase",
                  color: hi,
                  lineHeight: 1.2,
                  marginBottom: S * 0.9,
                  whiteSpace: "nowrap",
                  opacity: slugE,
                  transform: `translateY(${((1 - slugE) * S).toFixed(2)}px)${glide(midway(slugE) && !travelling)}`,
                }}
              >
                {b.slug}
              </div>
              {lines.map((line, li) => (
                <div
                  key={`${line.join(" ")}${String(li)}`}
                  style={{
                    height: F * LH,
                    lineHeight: `${F * LH}px`,
                    fontSize: F,
                    fontWeight,
                    whiteSpace: "pre",
                    letterSpacing: `${LINE_TRACK}em`,
                  }}
                >
                  {line.map((word, wi) => {
                    const s0 = write.start + write.beat("words") + idx * step;
                    idx++;
                    const e = interpolate(t, [s0, s0 + rise], [0, 1], {
                      ...CLAMP,
                      easing: EASE_OUT,
                    });
                    return (
                      <span
                        key={`${word}${String(wi)}`}
                        style={{
                          display: "inline-block",
                          color: ink,
                          opacity: e * inkOpacity,
                          transform: `translateY(${((1 - e) * F * 0.4).toFixed(2)}px)${glide(midway(e) && !travelling)}`,
                          marginRight:
                            wi < line.length - 1
                              ? `${adv(" ").toFixed(3)}em`
                              : 0,
                        }}
                      >
                        {word}
                      </span>
                    );
                  })}
                </div>
              ))}
            </div>
          );
        })}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// Three story beats: the setup writes in, the snag writes in and falls to the
// bottom, dimming, the resolution writes in and climbs to the top, taking the
// accent. Frames on the 30 fps scene timeline, after `delay`; the whole
// schedule stretches with the clip (`length / 180`, within 0.75–1.6). The
// ids are public: a saved `timing` prop refers to them.

export type StoryDipElementId =
  | "setup"
  | "snag"
  | "fall"
  | "resolution"
  | "climb";

interface Beat {
  slug: string;
  line: string;
}

export interface StoryDipTimingProps {
  setup?: Beat;
  snag?: Beat;
  resolution?: Beat;
}

export const DEFAULT_SETUP: Beat = {
  slug: "Wednesday, 4:00 PM",
  line: "Leo’s film was one render away.",
};
export const DEFAULT_SNAG: Beat = {
  slug: "4:05 PM",
  line: "Then the client sent a new logo.",
};
export const DEFAULT_RESOLUTION: Beat = {
  slug: "4:15 PM",
  line: "One prop later, every scene had it.",
};

/** A beat's slug rises over `RISE`; its words follow from `WORDS_AT`. */
const RISE = 14;
const WORDS_AT = 4;
/** The snag bounces `BOUNCE` after it lands and settles by `SETTLE`. */
const BOUNCE = 5;
const SETTLE = 12;
/** The resolution takes the accent from `LIFT_AT` into its climb. */
const LIFT_AT = 8;

/** The words of a beat's line, split on any whitespace. */
export function lineWords(line: string) {
  return line.split(/\s+/).filter(Boolean);
}

// `setup`, `snag` and `resolution` write their beat in: the slug over `rise`,
// then the words from `words`, `step` apart, each over `rise`. `fall` drops
// the snag to the bottom (and bounces it), `climb` lifts the resolution to
// the top. Each element follows the one before.
export const storyDipTimeline = defineTimeline<
  StoryDipElementId,
  StoryDipTimingProps
>(
  (
    {
      setup = DEFAULT_SETUP,
      snag = DEFAULT_SNAG,
      resolution = DEFAULT_RESOLUTION,
    },
    { length },
  ) => {
    const k = Math.min(1.6, Math.max(0.75, length / 180));
    const at = (f: number) => f * k;
    const inAt = [at(2), at(30), at(86)];
    const fallA = at(54);
    const fallB = at(70);
    const climbA = at(108);
    const climbB = at(132);
    const write = (
      id: "setup" | "snag" | "resolution",
      b: Beat,
      i: number,
    ): TimelineElement<StoryDipElementId> => {
      const count = lineWords(b.line).length;
      const step = Math.min(2.4, 14 / Math.max(1, count));
      return {
        id,
        lane: id === "setup" ? "Setup" : id === "snag" ? "Snag" : "Resolution",
        label: b.slug,
        start: inAt[i],
        length: WORDS_AT + Math.max(0, count - 1) * step + RISE,
        beats: { rise: RISE, words: WORDS_AT, step },
      };
    };
    return [
      write("setup", setup, 0),
      { ...write("snag", snag, 1), follows: "setup" },
      {
        id: "fall",
        lane: "Snag",
        label: "fall",
        start: fallA,
        length: fallB - fallA,
        follows: "snag",
        beats: { bounce: BOUNCE, settle: SETTLE },
      },
      { ...write("resolution", resolution, 2), follows: "fall" },
      {
        id: "climb",
        lane: "Resolution",
        label: "climb",
        start: climbA,
        length: climbB - climbA,
        follows: "resolution",
        beats: { lift: LIFT_AT },
      },
    ];
  },
);
